"""Build linked source contracts from reviewed captures; no Azure access."""
import ast,collections,hashlib,json,re
from pathlib import Path

MAPPING={
'aga-bayrate':'bayrate-app','aga-chapter-finder-update':'chapter-finder-update-app','aga-chapter-rewards-admin':'chapter-rewards-admin-app','aga-chapter-rewards-automation':'chapter-rewards-automation-app','aga-chapter-rewards-display':'chapter-rewards-display-app','aga-clubexpress-mail':'clubexpress-mail-app','aga-clubexpress-sso-probe':'clubexpress-sso-probe-app','aga-events':'events-app','aga-membership-functions':'membership-data-app','aga-membership-functions3':'membership-functions3-app','aga-news-archive-viewer':'news-article-archive-viewer-app','aga-ratings-explorer':'ratings-explorer-app','aga-ratings-explorer-display':'ratings-explorer-display-app','aga-ratings-explorer-sgf-20260407t2105':'ratings-explorer-app','aga-ratings-sgf-upload':'ratings-sgf-upload-app','go-weiqi-baduk-news-index':'go-weiqi-baduk-news-index-app'}
INTEGRATIONS={
'aga-bayrate':'Azure SQL rating/reward writes and snapshot refresh requests. Preserve operator authorization, rerun reconciliation and snapshot ownership.',
'aga-chapter-finder-update':'Chapter update request/review workflow, Entra/admin authorization and ClubExpress push-attempt ledger. Approval/push routes have production side effects.',
'aga-chapter-rewards-admin':'Chapter balances, redemptions, transfers, admin scopes and receipt blob storage. Preserve approval and authorization rules.',
'aga-chapter-rewards-automation':'Rewards SQL procedures, award/expiry/snapshot timers and Gmail renewal digest. One scheduler/mail owner only.',
'aga-chapter-rewards-display':'Public chapter balances and reward reporting from Azure SQL; preserve read-only display behavior.',
'aga-clubexpress-mail':'Gmail OAuth polling, ClubExpress CSV/email parsers, staged event processing, archive blobs and MySQL reference sync. MySQL is an external reference contract; its schema is not the Azure SQL export and requires separate migration assessment.',
'aga-clubexpress-sso-probe':'ClubExpress SSO callback/token investigation and capture storage. Preserve callback/token validation; do not publish captured user tokens.',
'aga-events':'Entra/EasyAuth plus application role checks; SQL event/registration ledgers; Gmail messages; Zoom meeting creation; workshop timers and QR downloads. Preserve exactly one message/meeting worker owner and idempotency.',
'aga-membership-functions':'Member/chapter imports, lookup and TD-list routes; legacy mailbox/MySQL paths coexist. Settings/enablement determine which timers own work. aga-lookup-app and tdlists-app are reference folders, not extra deployments. External MySQL definitions require separate assessment.',
'aga-membership-functions3':'Legacy rating history HTML/SVG using SQL member names and two packaged CSV datasets. Data files are deliberately excluded from public Git; a private cutover transfer is required.',
'aga-news-archive-viewer':'SQL and blob-backed archived articles, assets/member matches, external news synchronization and public display. Article bodies/mailbox content are production data, not source assets.',
'aga-ratings-explorer':'Legacy mixed Ratings Explorer, BayRate, reward and SGF surfaces; SQL, snapshot blobs/queues, Leago import and embedded WGo assets. Keep its package distinct from the older staging variant.',
'aga-ratings-explorer-display':'Public Ratings Explorer, SVG/SGF viewer and snapshot timers/queue workers. Snapshot blobs are runtime data; WGo scripts/artwork are committed assets.',
'aga-ratings-explorer-sgf-20260407t2105':'Older running mixed staging variant with its own source and configuration. Do not overwrite it with aga-ratings-explorer source or assume it is disposable.',
'aga-ratings-sgf-upload':'Authenticated SGF archive/import matching, SQL game records, blob upload and snapshot refresh. Preserve import authorization and replacement rules.',
'go-weiqi-baduk-news-index':'External news sites, translation service, spaCy name indexing, blob-backed index/history, timer and queue processing. Preserve translation budget/pacing and queue deduplication.'}

def main():
 repo=Path(__file__).resolve().parents[1];docs=repo/'docs';out=docs/'azure-apps';out.mkdir(exist_ok=True)
 inv=json.loads((docs/'azure-capture/inventory.json').read_text());sqlroot=repo/'sql/azure-baseline';sqlindex=json.loads((sqlroot/'index.json').read_text())
 objects=json.loads((sqlroot/'_database/objects.json').read_text());byid={o['object_id']:o for o in objects};index={o['schema']+'.'+o['name']:o for o in sqlindex['objects']}
 deps=json.loads((sqlroot/'_database/dependencies.json').read_text());verification={v['app']:v for v in json.loads((docs/'azure-capture/verification.json').read_text())}
 sourcefiles=[p for p in repo.rglob('*.py') if not set(p.relative_to(repo).parts)&{'azure-baseline','interim-source','scripts'}]
 maplines=['# Azure source map','', '**Source recovery: all 16 apps recovered; all live entry-point hashes match.** No Azure deployments, data, settings, credentials, schedules or routing changed. Migration has not started.','', 'Repository: [gurujeetkhalsa/aga](https://github.com/gurujeetkhalsa/aga) (existing public visibility retained). All services remain in this repository; no additional owner repository was found.','', 'Baseline revision: see [baseline publication record](baseline-revision.md). Immutable tag: [PREMIGRATION](https://github.com/gurujeetkhalsa/aga/tree/PREMIGRATION). Reconciliation: [read-only capture and three-way procedure](reconcile-azure-changes.md).','',f"Capture window: {inv['startedAt']} through {inv['finishedAt']}; SQL final capture: {sqlindex['capturedAt']}. Explicit AGA subscription `{inv['subscription']}`, tenant `{inv['tenant']}`.",'', 'Azure inventory was queried live and includes stopped apps. The 16 names match the October 9 inventory: **no newly discovered or absent apps; all 16 currently Running**. Background inventory was consulted, but the source below was captured afresh.','', '| Azure app | Resource group | Exact deployed source (GitHub aga) | Normal development folder | Shared source / SQL definitions / configuration and deployment | Recovery |','|---|---|---|---|---|---|']
 allcomparisons={};appdeps={}
 for app in sorted(MAPPING):
  folder=MAPPING[app];root=repo/'azure-baseline'/app;m=json.loads((docs/'azure-capture/manifests'/f'{app}.json').read_text());cfg=json.loads((docs/'azure-capture/config'/f'{app}.json').read_text());v=verification[app]
  texts={n:(root/n).read_text(encoding='utf-8-sig',errors='replace') for n in m['files'] if Path(n).suffix in {'.py','.sql','.html','.js','.md'}}
  # All packaged code is retained. Dependency candidates include SQL in support/admin paths.
  combined='\n'.join(s.replace('[','').replace(']','') for n,s in texts.items() if n.endswith(('.py','.sql')))
  direct={name for name in index if re.search(r'(?i)(?<![\w])'+re.escape(name)+r'(?![\w])',combined)}
  ids={o['object_id'] for o in objects if o['schema_name']+'.'+o['name'] in direct};closure=set(ids)
  changed=True
  while changed:
   before=set(closure)
   closure.update(d['referenced_id'] for d in deps if d['referencing_id'] in closure and d['referenced_id'] in byid)
   closure.update(o['object_id'] for o in objects if o['type'].strip()=='TR' and o['parent_object_id'] in closure)
   changed=before!=closure
  sqlnames=sorted({byid[x]['schema_name']+'.'+byid[x]['name'] for x in closure if byid[x]['schema_name']+'.'+byid[x]['name'] in index})
  candidates=set(re.findall(r'(?i)\b(?:FROM|JOIN|INTO|UPDATE|EXEC(?:UTE)?)\s+((?:dbo|membership|ratings|rewards|clubexpress|integration|staging|competition|events|dbrepl_meta)\.[A-Za-z_]\w*)',combined))
  unresolved=sorted(n for n in candidates if n.lower() not in {x.lower() for x in index})
  appdeps[app]={'direct':sorted(direct),'transitiveAndTriggers':sqlnames,'unresolvedLiteralReferences':unresolved,'dynamicSqlCompleteness':'unknown; review constructed SQL and external MySQL against source before conversion'}
  comparison=[]
  for n,h in m['files'].items():
   if n.startswith('bayrate/'):dev=repo/n
   else:dev=repo/folder/n
   local=repo/'interim-source/playground-current'/folder/n
   if n.startswith('bayrate/'):local=repo/'interim-source/playground-current'/n
   def compare(p):
    if not p.is_file():return 'absent'
    b=p.read_bytes()
    if hashlib.sha256(b).hexdigest()==h:return 'identical'
    if b.replace(b'\r\n',b'\n')==(root/n).read_bytes().replace(b'\r\n',b'\n'):return 'line endings only'
    return 'different'
   newfolders={'chapter-finder-update-app','events-app','news-article-archive-viewer-app','ratings-sgf-upload-app','go-weiqi-baduk-news-index-app','membership-functions3-app'}
   comparison.append({'deployedFile':n,'developmentPath':str(dev.relative_to(repo)).replace('\\','/'),'developmentComparison':compare(dev),'githubAtCaptureComparison':'absent' if folder in newfolders else compare(dev),'localSnapshotComparison':compare(local)})
  allcomparisons[app]=comparison
  shared=[]
  for n in sorted(n for n in m['files'] if n.endswith('.py') and '/tests/' not in n and not n.startswith('tests/')):
   if n=='function_app.py':continue
   maintained=repo/n if n.startswith(('bayrate/','rewards/','shared/')) and (repo/n).exists() else repo/folder/n
   if not maintained.exists():
    candidates2=[p for p in sourcefiles if p.name==Path(n).name]
    exact=[p for p in candidates2 if hashlib.sha256(p.read_bytes()).hexdigest()==m['files'][n]]
    maintained=exact[0] if exact else (candidates2[0] if len(candidates2)==1 else None)
   shared.append((n,str(maintained.relative_to(repo)).replace('\\','/') if maintained else None))
  summary='; '.join(sorted({x.split('/')[0] if '/' in x else x for x,_ in shared})) or 'no imported application modules'
  maplines.append(f'| `{app}` | `{m["resourceGroup"]}` | [azure-baseline/{app}/](../azure-baseline/{app}/) | [{folder}/](../{folder}/) | [Shared modules](azure-apps/{app}.md#shared-and-application-modules); [SQL: {len(sqlnames)} definitions](azure-apps/{app}.md#database); [configuration/deploy](azure-apps/{app}.md#configuration-and-deployment) | Recovered; runtime verified |')
  lines=[f'# {app}','',INTEGRATIONS[app],'',f'- Repository: [gurujeetkhalsa/aga](https://github.com/gurujeetkhalsa/aga). Resource group: `{m["resourceGroup"]}`.',f'- Exact captured source: [azure-baseline/{app}/](../../azure-baseline/{app}/). Development: [{folder}/](../../{folder}/).',f'- Host: `{m["hostname"]}`; state `{m["state"]}`; runtime `{json.dumps(m["runtime"])}`.',f'- Capture: `{m["capturedAt"]}`; source status: **{m["status"]}**.',f'- Active package: `{m["packageLocation"]}`. SHA-256 `{m["packageSha256"]}`.',f'- Release metadata and individual file hashes: [manifest](../azure-capture/manifests/{app}.json). Runtime `function_app.py` byte hash matches captured source.', '', '## Shared and application modules','', '| Captured module | Maintained development copy |','|---|---|']
  for n,d in shared:lines.append(f'| [{n}](../../azure-baseline/{app}/{n}) | '+(f'[{d}](../../{d})' if d else '**Unknown**: no unambiguous maintained counterpart; use captured source and establish ownership before edits')+' |')
  if not shared:lines.append('| Entry point is self-contained application code | See `function_app.py` |')
  lines+=['','These are package-local copies, not links to the repository root. Their versions may differ between apps. Never deduplicate merely by filename. Third-party imports are declared in [requirements.txt](../../azure-baseline/'+app+'/requirements.txt); the [static verification report](../azure-capture/verification.json) records the reachable module graph.','','## Database','', '| SQL definition | Relationship | Classification |','|---|---|---|']
  for name in sqlnames:
   o=index[name];lines.append(f'| [{name}](../../sql/azure-baseline/{o["path"]}) | '+('literal reference in packaged source' if name in direct else 'catalog dependency or attached trigger')+' | '+o['classification']+' |')
  if not sqlnames:lines.append('| No Azure SQL literal references found | Inspect config and dynamic paths | N/A |')
  lines+=['','Every SQL file has a metadata companion. [Database permissions](../../sql/azure-baseline/_database/permissions.sql), [principals](../../sql/azure-baseline/_database/principals.json), [schemas](../../sql/azure-baseline/_database/schemas.sql), [full-text definitions](../../sql/azure-baseline/_database/fulltext.sql) and [all dependency edges](../../sql/azure-baseline/_database/dependencies.json) are part of the contract.','', '**Dependency analysis limit:** dynamic SQL targets and external database definitions are unknown until each constructed SQL path is checked. Literal matching plus catalog closure is evidence, not proof that all runtime branches execute. Triggers classified as replication support must be evaluated separately from application behavior.']
  if unresolved:lines+=['','**Unresolved literal references:** '+', '.join('`'+x+'`' for x in unresolved)+'. Check existence, database target and feature enablement before migration. These are not silently substituted with similarly named objects.']
  lines+=['','## Configuration and deployment','',f'[Sanitized live settings, EasyAuth, route bindings, schedules and enablement](../azure-capture/config/{app}.json). Values marked `<supplied securely>` come from the existing Azure app setting/identity and must be provisioned through the future VM secret store. No secret values are in Git.', '', '[Storage container/queue inventory](../azure-capture/storage-contract.json). App-specific setting names and binding `connection`/`queueName`/`schedule` fields identify its resources. Dynamically constructed blob prefixes remain in the source. Do not infer timer ownership from app names alone.','',f'[Captured host configuration](../../azure-baseline/{app}/host.json). [Captured dependency declaration](../../azure-baseline/{app}/requirements.txt). '+(f'[Original packaged operations notes](../../azure-baseline/{app}/README.md).' if (root/'README.md').exists() else 'No original deployment script was embedded in the release; use the reproducible source-packaging command below.'),'','Build a reviewed source ZIP without executing code or contacting Azure:','','```powershell',f'python scripts/package_baseline.py {app} --output ../packages/{app}-source.zip','```','', 'For a separately authorized future Azure deployment, install the declared dependencies using the recorded Python version or use the Azure remote build. The historical deployment interface is:', '', '```powershell',f'az functionapp deployment source config-zip --subscription {inv["subscription"]} --resource-group {m["resourceGroup"]} --name {app} --src ../packages/{app}-source.zip --build-remote true','```','','**Do not execute that deployment command during baseline or reconciliation work.** Source ZIPs omit installed dependencies and production data. Deployment scripts embedded in the package are preserved; existing repository scripts are under [scripts/](../../scripts/). This command records the interface and is not a deployment performed by this task.','','## Routes, authentication and schedules','','| Function | Trigger contract | Enabled |','|---|---|---|']
  for f in cfg['functions']:
   bindings=(f.get('config') or {}).get('bindings',[]);display=[]
   for b in bindings:
    if 'trigger' in b.get('type','').lower():display.append('; '.join(f'{k}={b[k]}' for k in ('type','route','methods','authLevel','schedule','queueName','connection') if k in b))
   lines.append('| `'+f['name']+'` | '+('<br>'.join(display)).replace('|','\\|')+' | '+str(not f.get('isDisabled',False))+' |')
  lines+=['','Trigger ANONYMOUS does not bypass handler/EasyAuth authorization. Preserve the checks in the entry point and imported auth modules. Azure settings may disable a trigger independently; consult both settings and binding metadata.','','## Differences and verification','',f'{len(m["files"])} captured source/assets files. Static syntax, reachable imports, per-file hashes and ZIP CRC checks passed. No handler was invoked against production. [Per-file deployed/development/local comparison](../azure-capture/source-comparison.json) distinguishes the original GitHub development layout and preserved local work.','', 'The normal development folder may lag or diverge from the deployment. Future VM work starts from this appâ€™s captured behavior; do not overwrite newer development work. Use a separate `vm-stack/` implementation when migration begins.']
  if app=='aga-events':lines+=['','Workshop QR assets and their current target `https://aga-events.azurewebsites.net/events/learn-go-in-an-hour` are retained unchanged. Rehearsal and chapter referral targets are constructed by the captured source. No redirect/routing changes were made.']
  if app=='aga-membership-functions3':lines+=['','## Private data prerequisites','','The original SCM archive is SquashFS despite its `.zip` suffix. It was decoded with `dissect.squashfs`; live VFS returned HTTP 200 and matched its entry point. No replacement code was invented.','','`data/aga-ratings.csv` and `data/legacy-bayrate-best-event-ratings.csv` are required production datasets, excluded from public Git under the userâ€™s data restriction. Generated `legacy_bayrate_*.json` experiments are also excluded. Transfer the CSVs privately from the current SCM package during the separately authorized data migration, or use the `LEGACY_CHART_<FILENAME_NORMALIZED>` environment overrides documented by `_resolve_data_file`. Their absence from Git is intentional; this source package alone cannot serve actual rating history without those datasets.']
  (out/f'{app}.md').write_text('\n'.join(lines)+'\n',encoding='utf-8')
 maplines+=['','## Source and data boundaries','','`azure-baseline/` is immutable captured-source evidence; all own modules and safe static assets are retained per app. Installed dependencies, caches, private settings and generated/runtime data are excluded. The classic chart app needs two private CSV datasets; see [its data prerequisite](azure-apps/aga-membership-functions3.md#private-data-prerequisites). This is a complete source/schema capture, not a production data backup or a ready-to-run migration.','','Existing top-level development folders and Git history were preserved. Six previously missing deployable app folders were seeded from captured source. `interim-source/` records four local worktrees with hashes/original revisions. Local branches/staged/untracked state were left unchanged; sensitive/generated local material remains private. Use `vm-stack/` for the future single-instance implementation after checking these contracts; it has not been created or deployed in this task.','','## SQL and storage estate','','SQL server `aga-sql-server.database.windows.net`, resource group `aga-data-platform`: live app database `aga-membership` (Online), `master` (system database), and `aga-membership-pre-bayrate-rerun-20260827-224520` (Paused historical restore). All captured SQL settings target `aga-membership`. The paused restore database was not resumed or treated as production.','','Storage account `agafunc0522` (StorageV2), same resource group. [Exact container and queue names](azure-capture/storage-contract.json); no container contents/queue messages were captured. The leftover `app-package-agamembershipfunctions2-0456272` container is not an additional current Function App.','','[Live SQL index](../sql/azure-baseline/index.json): 84 tables, 77 procedures, 16 views, 8 triggers, 1 function, 1 sequence; 242 defaults, 107 checks, 113 keys, 79 foreign keys, 207 heap/index catalog records, 1 full-text index and 311 permission records. Zero unavailable module definitions. SQL plus metadata companions preserve the complete live catalog contract. [Application/tooling classification and migration coverage](sql-baseline-coverage.md).','','The previously missing `integration.news_archive_article_member_match` table and all seven named procedures are present, including `dbrepl_meta.ensure_capture`. Replication triggers and SQL diagram support are explicitly classified as tooling/replication, not application functionality.','','## Remaining migration analysis','','No app source or static asset recovery is unresolved. Dynamic SQL targets, optional runtime branches and external MySQL definitions still require migration analysis; each app page labels that limit and any literal reference absent from live SQL. Ordinary database/blob/queue changes require the separate consistent data/delta cutover described in the reconciliation instructions. Do not enable duplicate mail, Zoom, reward, import, queue or timer owners.','','[Verification](azure-capture/verification.json), [package/release manifests](azure-capture/manifests/), [configuration contracts](azure-capture/config/) and [source comparison](azure-capture/source-comparison.json) are the supporting evidence.']
 (docs/'azure-source-map.md').write_text('\n'.join(maplines)+'\n',encoding='utf-8')
 for name,data in [('source-comparison.json',allcomparisons),('sql-dependencies.json',appdeps)]: (docs/'azure-capture'/name).write_text(json.dumps(data,indent=2,sort_keys=True)+'\n',encoding='utf-8')
 # Compare live definitions with pre-existing source-controlled SQL (exclude live copies).
 sqlfiles=[p for p in repo.rglob('*.sql') if not set(p.relative_to(repo).parts)&{'azure-baseline','interim-source'}]
 sqltexts={p:p.read_text(encoding='utf-8-sig',errors='replace').replace('[','').replace(']','').lower() for p in sqlfiles}
 coverage=['# Live SQL definitions and source migration coverage','','Live metadata is authoritative for capture. A source-file mention is not proof a migration was applied. SQL Server DDL here is evidence; PostgreSQL migrations must be designed and ordered separately.','', '| Object | Type | Classification | Existing SQL source references |','|---|---|---|---|']
 for name,o in sorted(index.items()):
  refs=[]
  for p in sqlfiles:
   if name.lower() in sqltexts[p]:refs.append(p.relative_to(repo).as_posix())
  coverage.append(f'| [{name}](../sql/azure-baseline/{o["path"]}) | {o["type"]} | {o["classification"]} | '+('; '.join(f'[{p}](../{p})' for p in refs) if refs else '**Absent from existing SQL migration/export files**; retained from live metadata')+' |')
 coverage+=['','All objects retain their original schema paths. Use the classification column to separate application definitions from diagram/tooling and replication support. Permissions/principals and specialized catalog metadata are under `_database/`. No current identity/sequence counters or table rows were exported.']
 (docs/'sql-baseline-coverage.md').write_text('\n'.join(coverage)+'\n',encoding='utf-8')
 print('Built map and 16 app contracts; unresolved literal references:',{a:d['unresolvedLiteralReferences'] for a,d in appdeps.items() if d['unresolvedLiteralReferences']})
if __name__=='__main__':main()
